#include <iostream>
using namespace std;

int tree[100001], n;

int lowbit(int x) { return x & (-x); }

void add(int i, int v) {
    for (; i <= n; i += lowbit(i))
        tree[i] += v;
}

int sum(int i) {
    int s = 0;
    for (; i > 0; i -= lowbit(i))
        s += tree[i];
    return s;
}

int rangeSum(int l, int r) {
    return sum(r) - sum(l - 1);
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        add(i, x);
    }
    int q;
    cin >> q;
    while (q--) {
        int op;
        cin >> op;
        if (op == 1) {
            int idx, v;
            cin >> idx >> v;
            add(idx, v);
        } else {
            int l, r;
            cin >> l >> r;
            cout << rangeSum(l, r) << endl;
        }
    }
    return 0;
}

