#include <iostream>
using namespace std;

int tree[1001][1001];
int n, m;

int lowbit(int x) { return x & (-x); }

void add(int x, int y, int v) {
    for (int i = x; i <= n; i += lowbit(i))
        for (int j = y; j <= m; j += lowbit(j))
            tree[i][j] += v;
}

int sum(int x, int y) {
    int s = 0;
    for (int i = x; i > 0; i -= lowbit(i))
        for (int j = y; j > 0; j -= lowbit(j))
            s += tree[i][j];
    return s;
}

int rectSum(int x1, int y1, int x2, int y2) {
    return sum(x2, y2) - sum(x1 - 1, y2)
         - sum(x2, y1 - 1) + sum(x1 - 1, y1 - 1);
}

int main() {
    cin >> n >> m;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++) {
            int x;
            cin >> x;
            add(i, j, x);
        }
    int q;
    cin >> q;
    while (q--) {
        int op;
        cin >> op;
        if (op == 1) {
            int x, y, v;
            cin >> x >> y >> v;
            add(x, y, v);
        } else {
            int x1, y1, x2, y2;
            cin >> x1 >> y1 >> x2 >> y2;
            cout << rectSum(x1, y1, x2, y2) << endl;
        }
    }
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int tree[100001], a[100001];
int n;

int lowbit(int x) { return x & (-x); }

void update(int i) {
    for (int x = i; x <= n; x += lowbit(x)) {
        tree[x] = a[x];
        for (int j = 1; j < lowbit(x); j <<= 1)
            tree[x] = max(tree[x], tree[x - j]);
    }
}

int query(int i) {
    int res = a[i];
    for (int x = i; x > 0; x -= lowbit(x))
        res = max(res, tree[x]);
    return res;
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        update(i);
    }
    int q;
    cin >> q;
    while (q--) {
        int op;
        cin >> op;
        if (op == 1) {
            int idx, v;
            cin >> idx >> v;
            a[idx] = v;
            update(idx);
        } else {
            int r;
            cin >> r;
            cout << query(r) << endl;
        }
    }
    return 0;
}
